mapper.select:
select  from ai_model_config
where del_flag = '0'

    and name like concat('%', #{name}, '%')


    and provider_type = #{providerType}


    and enabled = #{enabled}

order by field(is_default, 'Y', 'N'), id desc

select count(*) from ai_model_config
where name = #{name} and del_flag = '0'
and id != #{excludeId}

mapper.update:
update ai_model_config set is_default = 'N', update_by = #{updateBy}, update_time = sysdate()
where is_default = 'Y' and del_flag = '0'
and id != #{excludeId}
